Interface Figura
  Method Area() As Real;
EndInterface

Class Cuadrado Implements Figura
  Define lado As Real;
  Method Constructor(l As Real)
    This.lado <- l;
  EndMethod
  Method Area() As Real
    Return This.lado * This.lado;
  EndMethod
EndClass

Class Circulo Implements Figura
  Define radio As Real;
  Method Constructor(r As Real)
    This.radio <- r;
  EndMethod
  Method Area() As Real
    Return 3.0 * This.radio * This.radio;
  EndMethod
EndClass

Subroutine Describir<T: Figura>(figura As T)
  Write "Área: ", figura.Area();
EndSubroutine

Algorithm Figuras
  Describir(New Cuadrado(2.0));
  Describir(New Circulo(1.0));
EndAlgorithm
